from pathlib import Path
import os,json,hashlib
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[2];(R/'qa/model-upgrade').mkdir(parents=True,exist_ok=True);html=(R/'dist/INK-Street-Fighter-6.html').read_bytes()
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=os.environ['INK_CHROMIUM'],headless=True);p=b.new_page();errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html.decode());p.wait_for_function('window.INKDuel?.ready');rows=p.evaluate('''()=>{const A=SVG_FIGHTER,out=[];for(const id of INK.Schema.CHARACTERS){A.start(id,'ryu','training','classic',7);A.state.paused=true;document.getElementById('dummy').value='idle';A.teleport(0,400);A.teleport(1,1100);A.step();const f=A.fighters[0];let good=true;for(const move of ['sHP','sHK']){A.inputMove(0,move);for(let i=0;i<65;i++){A.step();A.renderFraction(1);if(i%8===0)good&&=![...document.querySelectorAll('#game path')].some(e=>/NaN|Infinity/.test(e.getAttribute('d')||''));}}const state=JSON.stringify([f.x,f.y,f.hp,f.push,A.geometry(f)]),count=document.querySelectorAll('#game *').length;A.renderFraction(1);const dom=document.getElementById('game').innerHTML;for(let i=0;i<10;i++)A.renderFraction(1);out.push({id,finite:good,pure:state===JSON.stringify([f.x,f.y,f.hp,f.push,A.geometry(f)]),deterministic:dom===document.getElementById('game').innerHTML,bounded:count===document.querySelectorAll('#game *').length,nodes:count});}return out;}''');b.close()
report={'sha256':hashlib.sha256(html).hexdigest(),'rows':rows,'errors':errors};(R/'qa/model-upgrade/motion.json').write_text(json.dumps(report,indent=2));print(json.dumps(report));assert not errors and all(all(r[k] for k in ['finite','pure','deterministic','bounded']) for r in rows)
